create table public.race_lore(
  race_id text primary key check(race_id in('human','elf','dwarf','half_orc','goblin','fallen')),
  name_th text not null,
  title_th text not null,
  summary_th text not null,
  origin_th text not null,
  culture_th text not null,
  homeland_th text not null,
  beliefs_th text not null,
  relations_th text not null,
  motto_th text not null,
  starting_location_id bigint not null references public.world_locations(id),
  accent_color text not null check(accent_color~'^#[0-9a-fA-F]{6}$'),
  sigil text not null,
  active boolean not null default true
);
alter table public.race_lore enable row level security;
create policy "Players can read race lore" on public.race_lore for select to authenticated using(active);

insert into public.race_lore(race_id,name_th,title_th,summary_th,origin_th,culture_th,homeland_th,beliefs_th,relations_th,motto_th,starting_location_id,accent_color,sigil)
select lore.race_id,lore.name_th,lore.title_th,lore.summary_th,lore.origin_th,lore.culture_th,lore.homeland_th,lore.beliefs_th,lore.relations_th,lore.motto_th,location.id,lore.accent,lore.sigil
from(values
('human','มนุษย์','ผู้ถักทอชะตา','ชนเผ่าอายุสั้นผู้สร้างอาณาจักรจากความทะเยอทะยาน การปรับตัว และพันธมิตรที่เปลี่ยนแปลงเสมอ','มนุษย์แห่งออเรเลียนสืบเชื้อสายจากกลุ่มผู้ลี้ภัยสี่สายที่มาพบกันริมแม่น้ำรุ่งอรุณ พวกเขาไม่มีบรรพบุรุษเหนือธรรมชาติ แต่สร้างประวัติศาสตร์ด้วยมือของตนเอง','ครอบครัว เมือง และอาชีพสำคัญกว่าสายเลือด เทศกาลของมนุษย์เต็มไปด้วยคำสาบานต่อหน้าสาธารณะและการแลกของที่ระลึก','นครรุ่งอรุณคือศูนย์กลางราชสำนัก กิลด์ และตลาดซึ่งผู้คนจากทุกเผ่าพบกัน','พวกเขาเชื่อว่าชะตาเป็นผืนผ้าที่ยังทอไม่เสร็จ การกระทำสำคัญกว่าคำพยากรณ์','มนุษย์สร้างพันธมิตรได้ง่ายแต่ถูกมองว่าเปลี่ยนใจเร็ว เอลฟ์ชื่นชมความกล้า ดวอร์ฟให้ค่ากับสัญญาที่รักษา','วันพรุ่งนี้ยังไม่ถูกเขียน','dawnspire','#d5b66c','✦'),
('elf','เอลฟ์','ผู้ฟังเสียงพงไพร','ทายาทแห่งป่าเก่า ผู้รับรู้กระแสเวทในรากไม้ สายน้ำ และความทรงจำของแผ่นดิน','ตำนานเล่าว่าเอลฟ์ตื่นขึ้นเมื่อแสงจันทร์แรกสะท้อนหยดน้ำบนต้นไม้โลก พวกเขาจึงได้ยินเสียงของสิ่งมีชีวิตที่เก่าแก่กว่าภาษา','ชุมชนเอลฟ์ตัดสินใจผ่านวงสนทนา ศิลปะและความทรงจำเป็นสมบัติส่วนรวม การทำลายธรรมชาติโดยไร้เหตุผลถือเป็นความอัปยศ','กรีนฮอลโลว์ตั้งอยู่ชายพงไพรเวอร์แดนต์และดูแลต้นไม้ศักดิ์สิทธิ์ซึ่งบันทึกชื่อผู้จากไป','ความตายคือการคืนเรื่องราวให้ผืนดิน จันทร์เต็มดวงเป็นเวลารำลึกและขอคำแนะนำจากบรรพชน','เอลฟ์ไว้ใจดรูอิดและผู้รักษาคำมั่น พวกเขาระแวงความเร่งรีบของมนุษย์และเหมืองที่ขยายตัวของดวอร์ฟ','จงฟังก่อนที่ป่าจะต้องตะโกน','greenhollow','#75a982','♢'),
('dwarf','ดวอร์ฟ','ผู้จารึกศิลา','ชนเผ่าแห่งขุนเขาผู้เก็บคำสาบานไว้ในโลหะและวัดคุณค่าคนจากผลงานที่ทนต่อกาลเวลา','ดวอร์ฟเชื่อว่าตนถูกสกัดจากหินแกนโลกด้วยค้อนของช่างตีเหล็กองค์แรก รอยแตกบนศิลาคือแผนที่บรรพบุรุษ','ทุกตระกูลมีตราช่าง งานชิ้นเอกหนึ่งชิ้นอาจใช้เวลาหลายชั่วอายุ การเลี้ยงฉลองเริ่มเมื่อส่งมอบงาน ไม่ใช่เมื่อเริ่มทำ','ชุมทางสโตนพาสเชื่อมเหมืองคริสตัลกับหุบเขา ลึกลงไปยังมีนครใต้ดินที่ปิดประตูหลังสงครามเก่า','คำสัตย์ที่สลักบนหินมีน้ำหนักเท่าชีวิต ไฟเตาหลอมเป็นสัญลักษณ์ของการเปลี่ยนความทุกข์ให้เป็นสิ่งมีค่า','ดวอร์ฟเคารพมนุษย์ที่ทำงานหนักและโต้เถียงกับเอลฟ์เรื่องการใช้ทรัพยากร พวกเขาไม่ลืมทั้งบุญคุณและหนี้แค้น','เหล็กจำทุกแรงค้อน','stonepass','#c28c58','◆'),
('half_orc','ครึ่งออร์ค','โล่แห่งชายแดน','ผู้เกิดระหว่างสองวัฒนธรรมและสร้างเกียรติด้วยการปกป้องผู้ที่ยอมรับพวกเขาเป็นพวกเดียวกัน','ครึ่งออร์ครุ่นแรกเกิดจากสันติภาพเปราะบางหลังสงครามทุ่งเถ้า ลูกหลานของพวกเขาปฏิเสธการเป็นหลักฐานของสงครามและเลือกเป็นผู้พิทักษ์ชายแดน','ครอบครัวที่เลือกเองสำคัญกว่าสายเลือด การประลองเป็นทั้งกีฬาและวิธีระงับข้อพิพาทโดยไม่ทำสงคราม','ซอลต์เมียร์และทุ่งเถ้าเป็นบ้านของกองคาราวานครึ่งออร์ค ผู้รู้เส้นทางน้ำใต้ดินและพายุทรายดีที่สุด','ความแข็งแกร่งมีไว้รับภาระแทนผู้ที่อ่อนแอกว่า การถอยเพื่อช่วยชีวิตไม่ถือเป็นความขลาด','พวกเขาระวังเจ้าหน้าที่เมืองแต่ผูกมิตรกับชาวบ้านและนักเดินทางง่าย ดวอร์ฟมักยอมรับฝีมือก่อนเชื้อสาย','กำลังที่ไร้เมตตาคือความอ่อนแอ','saltmere','#a56e57','▲'),
('goblin','ก็อบลิน','ผู้รอดจากรอยแยก','นักประดิษฐ์ตัวเล็กผู้เปลี่ยนของเหลือทิ้งเป็นเครื่องมือ และเปลี่ยนภัยพิบัติเป็นเส้นทางใหม่เสมอ','เมื่อรอยแยกกลืนเมืองเก่า เผ่าอื่นหนีออกมาแต่ก็อบลินสร้างบ้านในซากปรัก พวกเขารอดด้วยกับดัก ความอยากรู้อยากเห็น และการแบ่งปันทุกชิ้นส่วน','ชื่อของก็อบลินเปลี่ยนตามผลงานล่าสุด ตลาดแลกเปลี่ยนใช้ทั้งเหรียญ ข่าวลือ และชิ้นส่วนกลไกเป็นราคา','ริเวอร์เรสต์เป็นจุดรวมช่างซ่อมเกวียน คนส่งข่าว และครอบครัวก็อบลินซึ่งอาศัยใต้สะพานใหญ่','โชคไม่ใช่ของขวัญ แต่คือการเตรียมทางหนีไว้สามทาง วิญญาณเครื่องมือจะช่วยผู้ที่ดูแลมัน','มนุษย์ชอบสิ่งประดิษฐ์แต่ไม่ไว้ใจวิธีหาอะไหล่ เอลฟ์รำคาญเสียงดัง ส่วนดวอร์ฟมักกลายเป็นคู่แข่งทางงานช่าง','ของพังทุกชิ้นยังมีอีกหนึ่งชีวิต','riverrest','#91a85e','●'),
('fallen','ผู้ตกจากแสง','เศษดาวผู้ไร้นาม','ผู้มีเศษพลังสวรรค์แตกร้าวอยู่ในวิญญาณ ถูกตามหลอกหลอนด้วยอดีตที่ไม่มีใครจำได้ครบถ้วน','คืนหนึ่งดาวหกดวงร่วงเหนือสุสานเสียงกระซิบ ผู้รอดชีวิตตื่นขึ้นพร้อมวงแสงที่แตกและชื่อซึ่งถูกลบจากบันทึกสวรรค์','พวกเขาไม่มีอาณาจักร จึงรวมตัวเป็นวงเล็กเพื่อแลกเปลี่ยนความฝัน คำเตือน และวิธีควบคุมแสงที่อาจรักษาหรือเผาผลาญ','สุสานเสียงกระซิบคือจุดที่ความทรงจำแรกกลับคืน หลายคนเริ่มการเดินทางใกล้ประตูหินแต่ไม่กล้าเข้าไปเพียงลำพัง','พวกเขาตั้งคำถามว่าไถ่บาปได้หรือไม่หากจำความผิดไม่ได้ บางคนบูชาแสงเดิม บางคนเลือกปกป้องโลกที่รับตนไว้','ผู้คนหวาดกลัวเครื่องหมายสวรรค์ นักบวชแบ่งเป็นผู้ช่วยเหลือกับผู้ล่า เอลฟ์มักรับฟังโดยไม่ตัดสิน','แม้แสงแตกสลาย มันยังชี้ทางได้','whispervault','#9a83c2','☾')
)lore(race_id,name_th,title_th,summary_th,origin_th,culture_th,homeland_th,beliefs_th,relations_th,motto_th,location_slug,accent,sigil)
join public.world_locations location on location.slug=lore.location_slug;
